		case 11:
		case 15:
		case 16:
		case 26:
		{
			int num4 = (int)(p.camMgr.scroll.X / 3200f);
			int num5 = (int)(p.camMgr.scroll.Y / 1600f);
			for (int i = num4 - 1; i < num4 + 2; i++)
			{
				for (int j = num5 - 1; j < num5 + 2; j++)
				{
					if (i < 0 || j < 0 || i >= map.mapGrid.tX || j >= map.mapGrid.tY)
					{
						continue;
					}
					for (int k = 0; k < map.mapGrid.chunk[i, j].layer[l].Length; k++)
					{
						Seg seg = layer.seg[map.mapGrid.chunk[i, j].layer[l][k]];
						if (seg == null)
						{
							continue;
						}
						switch (Textures.tex[seg.textureIdx].GetCell(seg.idx).flags)
						{
						case 12:
							if (num2 == 0 || num2 == 15 || num2 == 16 || num2 == 26)
							{
								float num6 = (seg.loc - ScrollManager.scroll).LengthSquared();
								if (num6 < num3 || num3 < 0f)
								{
									waterLev = seg.loc.Y;
									num = seg.loc.X;
									num3 = num6;
								}
							}
							break;
