							if (num2 == 11)
							{
								waterLev = seg.loc.Y;
								num = seg.loc.X;
							}
							break;
						}
					}
				}
			}
			break;
		}
		}
		if (num2 == 0 && num < p.camMgr.scroll.X - 3000f)
