				Sound.PlaySpre(2, new Vector2(num, p.camMgr.scroll.Y), 1);
			}
		}
	}

	public static void Update()
	{
		waterDelta += Game1.frameTime * 0.095f;
		waterTheta += Game1.frameTime * 0.075f;
		if (waterDelta > 1f)
		{
			waterDelta--;
		}
		if (waterTheta > 1f)
		{
			waterTheta--;
		}
	}

	public static void Prepare(RenderTarget2D mainTarg)
	{
		if (!(waterLev <= -1f))
		{
			dev.SamplerStates[1] = SamplerState.LinearWrap;
			dev.SetRenderTarget(waterTarg);
			dev.Clear(new Color(0f, 0f, 0f, 0f));
			Rectangle value = new Rectangle(0, 0, (int)ScrollManager.screenSize.X, (int)ScrollManager.screenSize.Y);
			Rectangle destinationRectangle = new Rectangle
			{
				X = 0,
				Y = 0,
				Width = waterTarg.Width,
				Height = waterTarg.Height
			};
			float value2 = ScrollManager.GetScreenLoc(new Vector2(0f, waterLev), 0).Y / ScrollManager.screenSize.Y;
			if (waterEffect != null)
			{
				waterEffect.Parameters["horizon"].SetValue(value2);
				waterEffect.Parameters["delta"].SetValue(6.28f - waterDelta);
				waterEffect.Parameters["theta"].SetValue(6.28f - waterTheta);
				waterEffect.Parameters["SampleTexture"].SetValue(mainTarg);
				waterEffect.Parameters["WaterImg"].SetValue(waterTex);
				SpriteTools.BeginOpaque(waterEffect);
			}
			else
			{
				SpriteTools.BeginAlpha();
			}
			SpriteTools.sprite.Draw(mainTarg, destinationRectangle, value, Color.White, 0f, default, SpriteEffects.None, 0f);
			SpriteTools.End();
			dev.Textures[0] = null;
			dev.Textures[1] = null;
		}
	}

	public static void Draw()
	{
		if (!(waterLev <= -1f))
		{
			SpriteTools.BeginAlpha();
			SpriteTools.sprite.Draw(waterTarg, new Vector2(0f, ScrollManager.GetScreenLoc(new Vector2(0f, waterLev), 0).Y), new Rectangle(0, 0, waterTarg.Width, waterTarg.Height), Color.White, 0f, default, new Vector2(ScrollManager.screenSize.X / (float)waterTarg.Width, ScrollManager.screenSize.Y / (float)waterTarg.Height), SpriteEffects.None, 0f);
			SpriteTools.End();
		}
	}
